+        {"loop",{0x3801,0xd1fd,0x4770}},
+        {"infinite",{0xe7fe}},
+        {"nested",{0x2800,0xd103,0x2900,0xd103,0x2201,0xe002,0x2202,0xe000,0x2203,0x4770}},
+        {"literal_gap",{0xe001,0xffff,0xffff,0x2201,0x4770}},
+        {"early_return",{0x2800,0xd100,0x4770,0x3001,0x4770}},
+        {"load_loop",{0x681a,0x3001,0x2804,0xd1fb,0x4770}},
+        {"store_loop",{0x6018,0x3001,0x2804,0xd1fb,0x4770}},
+        {"join_load",{0x681a,0x2a00,0xd101,0x2201,0xe000,0x2202,0x681c,0x4770}},
+        {"stack_diamond",{0xb510,0x2800,0xd101,0x2401,0xe000,0x2402,0x602c,0xbd10}},
+        {"nonentry_backedge",{0x2200,0x3201,0x2a03,0xd1fc,0x4770}},
+        {"outside_branch",{0x2800,0xd17f,0x2900,0xd100,0x2201,0x4770}},
+    };
+    unsigned checks=0;
+    for(const auto &[name,ops]:programs) {
+        const auto *code=reinterpret_cast<const std::uint8_t*>(ops.data());
+        const auto size=ops.size()*2;
+        std::vector<std::uint8_t> modules[2];
+        for(unsigned variant=0;variant<2;++variant) {
+            thumb_connected_regions=variant;
+            std::vector<wasm_func_def> funcs;
