+            for(auto *m:{&actual,&reference}) {m->write_code(0x1000,{code,code+size});m->write32(0x8000,seed);}
+            std::array<unsigned,256> states[2]{};
+            int counts[2]{};
+            for(unsigned variant=0;variant<2;++variant) {
+                auto &st=states[variant];
+                st[0]=seed;st[1]=seed;st[3]=st[5]=st[13]=0x8000;st[14]=0x2001;st[15]=0x1000;
+                st[state_offsets::CPSR/4]=(flags<<28)|48;st[state_offsets::MODE/4]=16;
+                st[state_offsets::NFLAG/4]=(flags>>3)&1;st[state_offsets::ZFLAG/4]=(flags>>2)&1;
+                st[state_offsets::CFLAG/4]=(flags>>1)&1;st[state_offsets::VFLAG/4]=flags&1;
+                st[state_offsets::TFLAG/4]=1;st[state_offsets::NIRQ/4]=1;st[state_offsets::NUM_INSTRS_TO_EXECUTE/4]=budget;
+                g_test_mem=variant?&actual:&reference;
