+                return false;
+            }
+            // The independent interpreter verifies exact guest work, rather
+            // than trusting matching translator implementations alone.
+            test_mem interpreted;interpreted.write_code(0x1000,{code,code+size});interpreted.write32(0x8000,seed);
+            r12l1::exclusive_monitor monitor(1);auto cpu=make_cpu(interpreted,monitor);
+            cpu->set_reg(0,seed);cpu->set_reg(1,seed);cpu->set_reg(3,0x8000);cpu->set_reg(5,0x8000);
