import fs from 'node:fs';
import assert from 'node:assert/strict';
const leb = n => { const out=[]; do { const b=n&127; n>>>=7; out.push(b|(n?128:0)); } while(n); return out; };
function reader(bytes, start=0) {
    return {bytes, pos:start, u() { let n=0, shift=0, b; do { b=this.bytes[this.pos++]; n|=(b&127)<<shift; shift+=7; } while(b&128); return n>>>0; },
        skipLeb() { while(this.bytes[this.pos++]&128); }};
}
function counted(bytes) {
    const r=reader(bytes,8), sections=[];
    while(r.pos<bytes.length) { const id=bytes[r.pos++], n=r.u(); sections.push([id,bytes.slice(r.pos,r.pos+n)]); r.pos+=n; }
    assert(!sections.some(([id])=>id===6),'Probe unexpectedly has globals');
    const out=[...bytes.slice(0,8)];
    const section=(id,data)=>out.push(id,...leb(data.length),...data);
    const increment=[0x23,0,0x42,1,0x7c,0x24,0];
    for(let [id,data] of sections) {
        if(id===7) {
            section(6,[1,0x7e,1,0x42,0,0x0b]); // mutable i64 global
            const e=reader(data), n=e.u();
            data=Uint8Array.from([...leb(n+1),...data.slice(e.pos),5,...Buffer.from('steps'),3,0]);
        }
        if(id===10) {
            const c=reader(data), functions=c.u(), code=[...leb(functions)];
            for(let f=0;f<functions;f++) {
                const size=c.u(), end=c.pos+size, start=c.pos, groups=c.u();
                for(let g=0;g<groups;g++){c.u();c.pos++;}
                const body=[...data.slice(start,c.pos)];
                while(c.pos<end) {
                    const begin=c.pos, op=data[c.pos++];
                    if([2,3,4,0x41,0x42].includes(op))c.skipLeb();
                    else if([0x0c,0x0d,0x10,0x20,0x21,0x22,0x23,0x24,0x3f,0x40].includes(op))c.u();
                    else if(op===0x0e){const n=c.u();for(let j=0;j<=n;j++)c.u();}
                    else if(op===0x11 || (op>=0x28&&op<=0x3e)){c.u();c.u();}
                    else if(op===0x43)c.pos+=4;
                    else if(op===0x44)c.pos+=8;
                    else assert([0,1,5,0x0b,0x0f,0x1a,0x1b].includes(op)||(op>=0x45&&op<=0xc4),`Unknown opcode ${op.toString(16)}`);
                    if(![2,3,5,0x0b].includes(op))body.push(...increment);
                    body.push(...data.slice(begin,c.pos));
                }
                assert.equal(c.pos,end);code.push(...leb(body.length),...body);
            }
            data=Uint8Array.from(code);
        }
        section(id,data);
    }
    return new WebAssembly.Module(Uint8Array.from(out));
}

// Check the counter independently on known branch, loop and call paths before
// using it to judge generated emulator code. Immediates are not instructions.
function checkCounter(bodies,arg,result,steps) {
    const raw=[0,97,115,109,1,0,0,0];
    const section=(id,b)=>raw.push(id,...leb(b.length),...b);
    section(1,[1,0x60,1,0x7f,1,0x7f]);section(3,[bodies.length,...bodies.map(()=>0)]);
    section(7,[1,5,...Buffer.from('probe'),0,0]);
    section(10,[bodies.length,...bodies.flatMap(body=>[...leb(body.length+1),0,...body])]);
    const instance=new WebAssembly.Instance(counted(Uint8Array.from(raw)));
    assert.equal(instance.exports.probe(arg),result);assert.equal(Number(instance.exports.steps.value),steps);
}
for(const condition of [0,1])checkCounter([[0x20,0,4,0x7f,0x41,7,5,0x41,9,0x0b,0x0b]],condition,condition?7:9,3);
checkCounter([[2,0x40,3,0x40,0x20,0,0x45,0x0d,1,0x20,0,0x41,1,0x6b,0x21,0,0x0c,0,0x0b,0x0b,0x20,0,0x0b]],3,0,28);
checkCounter([[0x20,0,0x10,1,0x0b],[0x20,0,0x41,0x7f,0x6a,0x0b]],8,7,5);

const probes=fs.readFileSync(process.argv[2],'utf8').split('\n').filter(l=>l.startsWith('THUMB_REGIONS ')).map(l=>JSON.parse(l.slice(14)));
const memory=new WebAssembly.Memory({initial:256,maximum:65536,shared:true});
const bytes=new Uint8Array(memory.buffer),words=new Uint32Array(memory.buffer),data=new DataView(memory.buffer);
const state=0x1000, host=0x100000, view=0x6000, pages=0x200000;
let helpers=[];
function access(write,width,p,a,v) {
    a>>>=0;helpers.push([write,width,a,v,words[(p+60)/4]]);
    const address=host+(a>=0x400000 ? a-0x400000 : a);
    if(write){if(width===4)data.setUint32(address,v,true);else if(width===2)data.setUint16(address,v,true);else data.setUint8(address,v);return;}
    return width===4?data.getUint32(address,true):width===2?data.getUint16(address,true):data.getUint8(address);
}
const env={memory,tlb_read32:(p,a)=>access(false,4,p,a),tlb_write32:(p,a,v)=>access(true,4,p,a,v),
    tlb_read16:(p,a)=>access(false,2,p,a),tlb_write16:(p,a,v)=>access(true,2,p,a,v),
    tlb_read8:(p,a)=>access(false,1,p,a),tlb_write8:(p,a,v)=>access(true,1,p,a,v)};
const rows=[];
for(let k=0;k<probes.length;k+=2) {
    const instances=probes.slice(k,k+2).map(p=>new WebAssembly.Instance(counted(Buffer.from(p.wasm,'base64')),{env}));
    for(const seed of [0,3])for(const budget of [0,1,2,3,4,5,6,8,16,32,40,100])for(const mapping of ['helper','page','arena']) {
        const results=instances.map(instance=>{
            bytes.fill(0,state,state+1024);bytes.fill(0,host+0x7000,host+0x9000);helpers=[];
            words[host/4+0x8000/4]=seed;
            words[state/4]=words[state/4+1]=seed;
            words[state/4+3]=words[state/4+5]=words[state/4+13]=mapping==='arena'?0x408000:0x8000;
            words[state/4+14]=0x2001;words[state/4+15]=0x1000;
            words[(state+784)/4]=48;words[(state+796)/4]=16;words[(state+828)/4]=1;
            words[(state+840)/4]=budget;words[(state+876)/4]=1;
            words[(state+852)/4]=mapping==='helper'?0:view;
            words[view/4]=0x400000;words[view/4+1]=0x4000000;words[view/4+2]=host;
            words[view/4+3]=pages;words[view/4+4]=(host-0x400000)>>>0;words[view/4+5]=mapping==='arena'?0xffffffff:0;
            for(const page of [7,8]) {words[(pages+page*8)/4]=host+page*4096;words[(pages+page*8)/4+1]=host+page*4096;}
            instance.exports.steps.value=0n;
            let executed=0,calls=0;
            while(calls<1000) {
                const fn=instance.exports['f_'+(words[state/4+15]&~1)];
                if(!fn || (calls && executed>=budget))break;
                words[(state+848)/4]=budget-executed;
                const n=fn(state)>>>0;assert(n<=budget-executed);
                executed+=n;calls++;if(!n)break;
            }
            const steps=Number(instance.exports.steps.value);
            if(mapping!=='helper')assert.equal(helpers.length,0, mapping+' must stay on its mapped fast path');
            words[(state+848)/4]=0;
            return {steps,executed,calls,helpers,state:[...words.subarray(state/4,state/4+256)],memory:Buffer.from(bytes.subarray(host+0x7000,host+0x9000))};
        });
        const [a,b]=results,label=JSON.stringify({name:probes[k].name,seed,budget,mapping});
        assert.equal(a.executed,b.executed,label);assert.deepEqual(a.state,b.state,label);
        assert.deepEqual(a.memory,b.memory,label);assert.deepEqual(a.helpers,b.helpers,label);
        rows.push({name:probes[k].name,seed,budget,mapping,before:a.steps,after:b.steps,before_calls:a.calls,after_calls:b.calls,guest_instructions:a.executed});
    }
}
const summary={reduced:rows.filter(r=>r.after<r.before).length,unchanged:rows.filter(r=>r.after===r.before).length,increased:rows.filter(r=>r.after>r.before).length};
fs.writeFileSync(process.argv[3],JSON.stringify({summary,rows},null,2)+'\n');console.log(summary);
for(const name of [...new Set(rows.map(r=>r.name))])console.log(name,rows.filter(r=>r.name===name&&r.budget===100&&r.mapping==='page').map(r=>[r.seed,r.before,r.after,r.before_calls,r.after_calls]));

